//! Rust port of the `inflection` C++ library.
//!
//! Everything in this port operates on raw bytes (`[u8]`) rather than `str`.
//! That is deliberate: the C++ original manipulates `std::string`, i.e. a byte
//! container, and uses the `<cctype>` classification functions under the "C"
//! locale. As a result it happily slices multi-byte UTF-8 sequences in half
//! (`truncate("héllo", 5)` yields the bytes `h \xC3 . . .`) and leaves any byte
//! >= 0x80 untouched when changing case. Working on bytes is the only way to
//! stay byte-for-byte identical with that behaviour.

pub mod ascii;
pub mod inflector;
pub mod rules;

pub use inflector::Inflector;

