//! Byte helpers that mirror `<cctype>` under the "C" locale.
//!
//! `std::toupper`/`std::tolower`/`std::isalnum` only ever touch the ASCII range
//! in the default locale, so bytes >= 0x80 must be passed through unchanged.

/// `std::toupper` for a single byte.
pub fn to_upper(b: u8) -> u8 {
    if b.is_ascii_lowercase() {
        b - 32
    } else {
        b
    }
}

/// `std::tolower` for a single byte.
pub fn to_lower(b: u8) -> u8 {
    if b.is_ascii_uppercase() {
        b + 32
    } else {
        b
    }
}

pub fn upcase(bytes: &[u8]) -> Vec<u8> {
    bytes.iter().copied().map(to_upper).collect()
}

pub fn downcase(bytes: &[u8]) -> Vec<u8> {
    bytes.iter().copied().map(to_lower).collect()
}

/// Uppercase the first byte, leaving the remainder alone.
pub fn upper_first(bytes: &[u8]) -> Vec<u8> {
    let mut out = bytes.to_vec();
    if let Some(first) = out.first_mut() {
        *first = to_upper(*first);
    }
    out
}

/// Lowercase the first byte, leaving the remainder alone.
pub fn lower_first(bytes: &[u8]) -> Vec<u8> {
    let mut out = bytes.to_vec();
    if let Some(first) = out.first_mut() {
        *first = to_lower(*first);
    }
    out
}

pub fn ends_with(bytes: &[u8], suffix: &[u8]) -> bool {
    bytes.len() >= suffix.len() && &bytes[bytes.len() - suffix.len()..] == suffix
}

/// Replace `suffix` at the end of `bytes` with `replacement`.
pub fn replace_suffix(bytes: &[u8], suffix: &[u8], replacement: &[u8]) -> Vec<u8> {
    let mut out = bytes[..bytes.len() - suffix.len()].to_vec();
    out.extend_from_slice(replacement);
    out
}

/// Index of the last occurrence of `needle`, i.e. `std::string::rfind`.
pub fn rfind(bytes: &[u8], needle: &[u8]) -> Option<usize> {
    if needle.is_empty() || needle.len() > bytes.len() {
        return None;
    }
    (0..=bytes.len() - needle.len())
        .rev()
        .find(|&i| &bytes[i..i + needle.len()] == needle)
}

