//! Inflection tables: uncountable words and the singularization rules.
//!
//! Every lookup here is case sensitive, matching the C++ library: `sheep` is
//! uncountable but `Sheep` is not, and the suffix rules only fire on lowercase
//! suffixes (`mice` -> `mouse`, while `Mice` is left alone).

use crate::ascii::{ends_with, replace_suffix};

/// Words that are identical in singular and plural form.
///
/// Checked before any rule, by both `pluralize` and `singularize`.
const UNCOUNTABLE: &[&[u8]] = &[
    b"equipment",
    b"information",
    b"rice",
    b"money",
    b"species",
    b"series",
    b"fish",
    b"sheep",
    b"jeans",
    b"police",
];

/// Ordered `(suffix, replacement)` singularization rules.
///
/// The first matching entry wins, so the more specific suffixes come first:
/// `axes` must be tried before `xes` (`waxes` -> `waxis`, not `wax`), and every
/// entry is tried before the catch-all "drop a trailing s".
///
/// Two quirks of the C++ tables are preserved on purpose, because the goal is
/// byte-identical output rather than linguistic correctness:
///   * `analyses` -> `analyasis` (misspelled in the original table)
///   * `ta`/`ia` -> `tum`/`ium` is an unanchored suffix rule, so `beta`
///     singularizes to `betum` just as `data` does to `datum`.
const SINGULAR_RULES: &[(&[u8], &[u8])] = &[
    (b"mice", b"mouse"),
    (b"lice", b"louse"),
    (b"ta", b"tum"),
    (b"ia", b"ium"),
    (b"quizzes", b"quiz"),
    (b"matrices", b"matrix"),
    (b"vertices", b"vertex"),
    (b"indices", b"index"),
    (b"axes", b"axis"),
    (b"crises", b"crisis"),
    (b"testes", b"testis"),
    (b"analyses", b"analyasis"),
    (b"bases", b"basis"),
    (b"diagnoses", b"diagnosis"),
    (b"parentheses", b"parenthesis"),
    (b"prognoses", b"prognosis"),
    (b"synopses", b"synopsis"),
    (b"theses", b"thesis"),
    (b"buses", b"bus"),
    (b"statuses", b"status"),
    (b"aliases", b"alias"),
    (b"oes", b"o"),
    (b"ves", b"fe"),
    (b"sses", b"ss"),
    (b"ches", b"ch"),
    (b"shes", b"sh"),
    (b"xes", b"x"),
];

pub fn is_uncountable(word: &[u8]) -> bool {
    UNCOUNTABLE.contains(&word)
}

/// The `([^aeiouy]|qu)ies$ -> \1y` rule.
///
/// The character class is matched case sensitively, which is why `cities`
/// becomes `city` and `yies` stays `yie`, yet `Yies` becomes `Yy`.
fn apply_ies_rule(word: &[u8]) -> Option<Vec<u8>> {
    if !ends_with(word, b"ies") || word.len() < 4 {
        return None;
    }
    let preceding = word[word.len() - 4];
    let is_vowel = matches!(preceding, b'a' | b'e' | b'i' | b'o' | b'u' | b'y');
    if is_vowel && !ends_with(word, b"quies") {
        return None;
    }
    Some(replace_suffix(word, b"ies", b"y"))
}

/// Apply the first matching singularization rule, if any.
pub fn apply_singular_rules(word: &[u8]) -> Option<Vec<u8>> {
    if let Some(result) = apply_ies_rule(word) {
        return Some(result);
    }
    for &(suffix, replacement) in SINGULAR_RULES {
        if ends_with(word, suffix) {
            return Some(replace_suffix(word, suffix, replacement));
        }
    }
    None
}

