//! The `inflection::Inflector` API.
//!
//! All entry points take and return raw bytes; see the module docs for why.

use super::ascii::{
    downcase, ends_with, lower_first, rfind, to_lower, to_upper, upcase, upper_first,
};
use super::rules;

pub struct Inflector;

impl Inflector {
    /// Present for parity with the C++ API, where it primes the rule tables.
    /// The Rust tables are `const`, so there is nothing to do.
    pub fn initialize() {}

    /// Uncountable words are returned untouched; everything else just gains an
    /// `s` (the C++ library has no irregular plural table, hence `person` ->
    /// `persons` and `dogs` -> `dogss`).
    pub fn pluralize(word: &[u8]) -> Vec<u8> {
        if rules::is_uncountable(word) {
            return word.to_vec();
        }
        let mut out = word.to_vec();
        out.push(b's');
        out
    }

    pub fn singularize(word: &[u8]) -> Vec<u8> {
        if rules::is_uncountable(word) {
            return word.to_vec();
        }
        // The only whole-word irregular; `xoxen` and `Oxen` are unaffected.
        if word == b"oxen" {
            return b"ox".to_vec();
        }
        // `news` (and anything ending in it) is already singular.
        if ends_with(word, b"news") {
            return word.to_vec();
        }
        if let Some(result) = rules::apply_singular_rules(word) {
            return result;
        }
        if ends_with(word, b"s") {
            return word[..word.len() - 1].to_vec();
        }
        word.to_vec()
    }

    pub fn is_plural(word: &[u8]) -> bool {
        Self::singularize(word) != word
    }

    pub fn is_singular(word: &[u8]) -> bool {
        !Self::is_plural(word)
    }

    /// `camelize` with the C++ default argument.
    pub fn camelize(word: &[u8]) -> Vec<u8> {
        Self::camelize_opt(word, true)
    }

    /// Joins `_`-separated segments, capitalizing the first byte of every
    /// segment except the leading one, which is copied verbatim.
    ///
    /// `lower_first` is the C++ default argument. Note that it does *not*
    /// lowercase anything: when it is false the first byte of the result is
    /// uppercased, and when it is true the result is left as built. That is why
    /// `camelize("HelloWorldFoo")` stays `HelloWorldFoo` instead of becoming
    /// `helloWorldFoo`.
    pub fn camelize_opt(word: &[u8], lower_first: bool) -> Vec<u8> {
        let mut out = Vec::with_capacity(word.len());
        for (index, segment) in word.split(|&b| b == b'_').enumerate() {
            if index == 0 {
                out.extend_from_slice(segment);
            } else {
                out.extend_from_slice(&upper_first(segment));
            }
        }
        if lower_first {
            out
        } else {
            upper_first(&out)
        }
    }

    /// Inserts `_` before every interior uppercase ASCII letter and lowercases
    /// it. Unlike Rails, `-` and `::` are left alone: `Foo::Bar` -> `foo::_bar`.
    pub fn underscore(word: &[u8]) -> Vec<u8> {
        let mut out = Vec::with_capacity(word.len());
        for (index, &byte) in word.iter().enumerate() {
            if byte.is_ascii_uppercase() {
                if index > 0 {
                    out.push(b'_');
                }
                out.push(to_lower(byte));
            } else {
                out.push(byte);
            }
        }
        out
    }

    pub fn classify(word: &[u8]) -> Vec<u8> {
        Self::camelize_opt(&Self::singularize(word), false)
    }

    pub fn tableize(word: &[u8]) -> Vec<u8> {
        Self::pluralize(&Self::underscore(word))
    }

    /// `_` becomes a space and the first byte is uppercased; the rest of the
    /// string keeps its original case and no `_id` suffix is stripped.
    pub fn humanize(word: &[u8]) -> Vec<u8> {
        let spaced: Vec<u8> = word
            .iter()
            .map(|&b| if b == b'_' { b' ' } else { b })
            .collect();
        upper_first(&spaced)
    }

    /// Lowercases everything, then uppercases the first byte of every
    /// space-separated word. Only `' '` separates words, so `hello_world`
    /// becomes `Hello_world`.
    pub fn titleize(word: &[u8]) -> Vec<u8> {
        let mut out = downcase(word);
        for index in 0..out.len() {
            if index == 0 || out[index - 1] == b' ' {
                out[index] = to_upper(out[index]);
            }
        }
        out
    }

    pub fn dasherize(word: &[u8]) -> Vec<u8> {
        word.iter()
            .map(|&b| if b == b'_' { b'-' } else { b })
            .collect()
    }

    /// Keeps alphanumerics (lowercased), turns spaces into `-`, drops
    /// everything else, then trims leading and trailing `-`.
    pub fn parameterize(word: &[u8]) -> Vec<u8> {
        let mut out = Vec::with_capacity(word.len());
        for &byte in word {
            if byte.is_ascii_alphanumeric() {
                out.push(to_lower(byte));
            } else if byte == b' ' {
                out.push(b'-');
            }
        }
        let start = out.iter().position(|&b| b != b'-').unwrap_or(out.len());
        let end = out.iter().rposition(|&b| b != b'-').map_or(start, |i| i + 1);
        out[start..end].to_vec()
    }

    pub fn upcase(word: &[u8]) -> Vec<u8> {
        upcase(word)
    }

    pub fn downcase(word: &[u8]) -> Vec<u8> {
        downcase(word)
    }

    /// Lowercases the whole word, then uppercases the first byte.
    pub fn capitalize(word: &[u8]) -> Vec<u8> {
        upper_first(&downcase(word))
    }

    /// Lowercases only the first byte.
    pub fn decapitalize(word: &[u8]) -> Vec<u8> {
        lower_first(word)
    }

    /// Words longer than `max_length` are cut to `max_length - 3` bytes plus an
    /// ellipsis. The cut is made in bytes, so it can split a UTF-8 sequence.
    pub fn truncate(word: &[u8], max_length: usize) -> Vec<u8> {
        if word.len() <= max_length {
            return word.to_vec();
        }
        // `substr(0, maxLength - 3)` in C++: for maxLength < 3 the subtraction
        // wraps around and the count is clamped to the string length.
        let keep = match max_length.checked_sub(3) {
            Some(keep) => keep.min(word.len()),
            None => word.len(),
        };
        let mut out = word[..keep].to_vec();
        out.extend_from_slice(b"...");
        out
    }

    /// Everything after the last `::`.
    ///
    /// The C++ implementation slices at `pos + 3` rather than `pos + 2`, so one
    /// extra byte is eaten: `demodulize("Test::cat")` is `at`, not `cat`. When
    /// that index runs past the end, `std::string::substr` throws
    /// `std::out_of_range` and the program aborts; `substr_from` reproduces it.
    pub fn demodulize(word: &[u8]) -> Vec<u8> {
        match rfind(word, b"::") {
            Some(pos) => substr_from(word, pos + 3),
            None => word.to_vec(),
        }
    }

    /// English ordinal suffixes: 1st, 2nd, 3rd, 4th, 11th, 21st, ...
    pub fn ordinalize(number: i64) -> Vec<u8> {
        let mut out = number.to_string().into_bytes();
        let absolute = number.unsigned_abs();
        let suffix: &[u8] = match (absolute % 100, absolute % 10) {
            (11 | 12 | 13, _) => b"th",
            (_, 1) => b"st",
            (_, 2) => b"nd",
            (_, 3) => b"rd",
            _ => b"th",
        };
        out.extend_from_slice(suffix);
        out
    }
}

/// `std::string::substr(pos)`, including the `std::out_of_range` behaviour of
/// an uncaught C++ exception: the message libstdc++ prints from
/// `std::terminate`, followed by `SIGABRT`.
fn substr_from(bytes: &[u8], pos: usize) -> Vec<u8> {
    if pos > bytes.len() {
        use std::io::Write;
        let _ = std::io::stdout().flush();
        eprintln!("terminate called after throwing an instance of 'std::out_of_range'");
        eprintln!(
            "  what():  basic_string::substr: __pos (which is {}) > this->size() (which is {})",
            pos,
            bytes.len()
        );
        let _ = std::io::stderr().flush();
        std::process::abort();
    }
    bytes[pos..].to_vec()
}

